class Solution {
  public int minOperations(String s1, String s2) {
    int n = s1.length();
    long needClear = 0, needSet = 0, edges = 0;
    boolean[] covered = new boolean[n];
    for (int i = 0; i < n; i++) {
      if (s1.charAt(i) == '0' && s2.charAt(i) == '1') needSet++;
      if (s1.charAt(i) == '1' && s2.charAt(i) == '0') needClear++;
    }
    for (int i = 0; i < n; i++) {
      if (s1.charAt(i) == '1' && s2.charAt(i) == '0' && !covered[i]) {
        if (n == 1) return -1;
        edges++;
        covered[i] = true;
        if (i + 1 < n) covered[i + 1] = true;
        else covered[i - 1] = true;
      }
    }
    return (int) (3 * edges + needSet - needClear);
  }
}
